from kivy.app import App
from kivy.uix.gridlayout import GridLayout
from kivy.uix.button import Button
from kivy.uix.behaviors import FocusBehavior
from kivy.uix.behaviors.compoundselection import CompoundSelectionBehavior
from kivy.core.window import Window
from kivy.properties import ListProperty

class SelectableGrid(FocusBehavior, CompoundSelectionBehavior, GridLayout):
    selected_nodes = ListProperty([])

    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self._typed_number = ""
        self._typed_number_time = 0
        Window.bind(on_key_down=self._on_key_down, on_key_up=self._on_key_up)
        self.selected_nodes = []

    def _on_key_down(self, window, key, scancode, codepoint, modifiers):
        if codepoint and codepoint.isdigit():
            from time import time
            now = time()
            if now - self._typed_number_time > 1:
                self._typed_number = ""
            self._typed_number_time = now
            self._typed_number += codepoint
            self.navigate_to_node_by_number(self._typed_number)
            return True
        elif key in (273, 274, 275, 276):  # up, down, right, left
            self.select_with_key_down(key, False)
            return True
        elif key == 32:  # space
            self.toggle_selection()
            return True
        return False

    def _on_key_up(self, window, key, scancode):
        pass

    def navigate_to_node_by_number(self, number_str):
        for child in self.children:
            if getattr(child, 'text', None) == number_str:
                self.select_node(child)
                break

    def select_node(self, node):
        if node not in self.selected_nodes:
            self.selected_nodes.append(node)
            self.apply_selection(node, True)
            self.print_selected_nodes()

    def deselect_node(self, node):
        if node in self.selected_nodes:
            self.selected_nodes.remove(node)
            self.apply_selection(node, False)
            self.print_selected_nodes()

    def toggle_selection(self):
        focus_node = self._get_focused_node()
        if focus_node:
            if focus_node in self.selected_nodes:
                self.deselect_node(focus_node)
            else:
                self.select_node(focus_node)

    def _get_focused_node(self):
        # Return the first selected node or the first child
        if self.selected_nodes:
            return self.selected_nodes[-1]
        elif self.children:
            return self.children[-1]
        return None

    def select_with_touch(self, node, touch=None):
        if node.collide_point(*touch.pos):
            if node in self.selected_nodes:
                self.deselect_node(node)
            else:
                self.select_node(node)
            return True
        return False

    def on_touch_down(self, touch):
        for child in self.children:
            if child.collide_point(*touch.pos):
                self.select_with_touch(child, touch)
                break
        return super().on_touch_down(touch)

    def apply_selection(self, node, selected):
        if selected:
            node.background_color = (0.2, 0.6, 1, 1)
        else:
            node.background_color = (1, 1, 1, 1)

    def print_selected_nodes(self):
        print("Selected nodes:", [getattr(node, 'text', '') for node in self.selected_nodes])

class TestApp(App):
    def build(self):
        grid = SelectableGrid(cols=5, spacing=5, padding=5, size_hint=(1, 1))
        for i in range(1, 41):
            btn = Button(text=str(i), background_color=(1, 1, 1, 1))
            btn.bind(on_touch_down=lambda instance, touch, btn=btn: grid.select_with_touch(btn, touch))
            grid.add_widget(btn)
        return grid

if __name__ == '__main__':
    TestApp().run()
